css:
/*
幽夜回廊 · 非官方阅读页主题。
素材来源：用户自行提供的《SiNiSistar2》解密资源（AES AssetBundle 反向提取的原始 PNG）。
  本次入库口径由用户裁定为「原图直接内联」，仅做**按帧横向拼接**（像素零改动）；
  成人向 / 恐怖向（血腥）素材已剔除，仅保留中性的角色部件、怪物动作、建筑陈设与 UI 底图。
版权归原作方所有；本主题不代表原作方，也不把这些素材重新声明为开源或 CC0。
逐项来源路径与 SHA-256 见同目录 sources.json（由 prepare-dungeon-hud-assets.py 记录）。
*/
/* 幽夜回廊 · 结构样式（壳 / 页眉活场景 / 纸页 / 页脚 HUD / 三态）
   契约面：--reader-* 变量族（与 --md-* 同源）、data-reader-theme 三态、
           装饰层一律 aria-hidden + 绝对定位（不参与正文测量）。
   配色来源：**从游戏原图实测**（大教堂图书馆全景 + 石墙），主调为近黑/冷灰石/暗血红/烛光金，
             —— 见 tools/reader-templates/dungeon-hud/SOURCES.md。 */

:root {
  --md-font-size: 18px;
  --md-line-height: 1.92;
  --reader-font-size: var(--md-font-size);
  --reader-line-height: var(--md-line-height);
  --reader-font-family: "Noto Serif CJK SC", "Source Han Serif SC", "Noto Sans CJK SC", Georgia, serif;
  --reader-paragraph-indent: 2em;
  --reader-paragraph-spacing: .62em;
  --reader-accent: #7a1c17;

  /* 全幅底图单源：同一张图在页眉/纸页/页脚三处取不同景位 ⇒ 只内联一份字节 */
  --dh-scene: url("data:image/png;base64,");
  /* 可平铺石墙纹理（512×512）：纸页的岩石底纹 **+ 区域 4（岩窟）底图** */
  --dh-stone: url("data:image/png;base64,");
  /* R4 区域底图（实拍，后两张已**等比降采样**）：城镇屋舍 / 墓道地面 */
  --dh-town: url("data:image/png;base64,");
  --dh-grave: url("data:image/png;base64,");
  /* R4 左右竖带点缀（4 小件合并为 1 张横向图集） */
  --dh-band: url("data:image/png;base64,");
  /* R4 弹道两帧精灵表——**单源变量**：同一张图在「技能特效」与「续页对话框」两处使用，
     必须走 CSS 变量，否则同一 data URI 会被内联两次 ⇒ 触发"内联次数 == 登记项数"失守。 */
  --dh-bolt: url("data:image/png;base64,");

  /* 三态之一「日间」—— 冷灰石室（暗黑系石质，非暖羊皮；与软件浅色主题协调） */
  --reader-text-color: #171614;
  --reader-page-background: #bcb8af;
  --dh-paper: #b5b1a8;
  --dh-paper-edge: #7c7972;
  --dh-dim: #4e4b45;
  --dh-line: rgba(20, 19, 17, .26);
  --dh-hp: #7a1c17;
  --dh-mp: #39506a;
  --dh-gold: #6b5a2a;
  --dh-hud: rgba(20, 19, 17, .12);
  --dh-requiem-glow: rgba(122, 28, 23, .42);
  --dh-veil: rgba(14, 14, 15, .56);
  --dh-fade: rgba(182, 178, 169, .92);
  /* 正文纸页幕（**唯一消费者**是 `.dh-paper::before`）：≥.95 ⇒ 石纹残余透出 ≤5%，
     只作纸面质感、不成暗斑（2026-10-20「正文区一大片阴影遮挡」修复，见 `.dh-paper` 注释）。 */
  --dh-veil-strong: rgba(181, 177, 168, .95);
  --dh-deco: .72;
}

html[data-reader-theme="night"] {
  --reader-text-color: #ddd8ce;
  --reader-page-background: #0c0d0f;
  --reader-accent: #c9a24a;
  --dh-paper: #101113;
  --dh-paper-edge: #34373c;
  --dh-dim: #8b8781;
  --dh-line: rgba(201, 162, 74, .22);
  --dh-hp: #a8261f;
  --dh-mp: #4a6b8e;
  --dh-gold: #c9a24a;
  --dh-hud: rgba(255, 255, 255, .06);
  --dh-requiem-glow: rgba(168, 38, 31, .46);
  --dh-veil: rgba(5, 5, 7, .58);
  --dh-fade: rgba(12, 13, 15, .90);
  --dh-veil-strong: rgba(9, 10, 12, .95);
  --dh-deco: .88;
}

html[data-reader-theme="eink"] {
  --reader-text-color: #141414;
  --reader-page-background: #ececeb;
  --reader-accent: #2c2c2c;
  --dh-paper: #f2f2f1;
  --dh-paper-edge: #b6b6b4;
  --dh-dim: #555555;
  --dh-line: rgba(0, 0, 0, .18);
  --dh-hp: #262626;
  --dh-mp: #6a6a6a;
  --dh-gold: #3a3a3a;
  --dh-hud: rgba(0, 0, 0, .07);
  --dh-requiem-glow: rgba(40, 40, 40, .32);
  --dh-veil: rgba(70, 70, 70, .46);
  --dh-fade: rgba(236, 236, 235, .92);
  --dh-veil-strong: rgba(238, 238, 237, .95);
  --dh-deco: .28;
}

/* 装饰强度档位（宿主下发 html[data-rp-decoration]） */
html[data-rp-decoration="none"] { --dh-deco: 0 }
html[data-rp-decoration="light"] { --dh-deco: .45 }
html[data-rp-decoration="medium"] { --dh-deco: .72 }
html[data-rp-decoration="strong"] { --dh-deco: 1 }

/* —— 页根安全区 reset（R1，archive 同款约定）——
   引擎基线把 `--reader-safe-*` 作为**内边距**施加在页根 `[data-reader-page]` 上；本主题的页眉是
   **全幅出血**设计（场景带本就该越过系统栏）⇒ 不需要这层内边距，显式清零。
   与引擎侧 `[data-reader-page]{box-sizing:border-box}` 共同保证 **页根总高恒 = 视口高**
   ⇒ 页脚不再被推出视口（真机铁证：`rb=878 > vp=854`，差 +24 = safe-top）。 */
[data-reader-page] { padding: 0 }

body {
  margin: 0;
  color: var(--reader-text-color);
  background: var(--reader-page-background);
  font: 400 var(--reader-font-size) / var(--reader-line-height) var(--reader-font-family);
}

/* —— 三行约束壳：场景带 / 正文 1fr / HUD ——
   装饰与插画全部 absolute ⇒ 增删装饰不改变正文测量与页数。
   ⚠️ 行高口径（R1，2026-10-19）：**页眉行 + 页脚行 ≤ 0.2 × 视口高**（保正文区 ≥80%，跨尺寸）。
   离线实测（`tools/reader-templates/verify-geometry-offline.py --multi`）标定：
     · 360×640 是**最紧**的一档（预算 128px）⇒ 页眉 min 48 / 页脚 min 44 才达标；
     · 高屏（≥854）由 `vh` 与上限共同约束（页眉 ≤80、页脚 ≤56）。
   密度靠**层数**补（多层叠加/多动效），**不靠高度**。 */
.dh-page {
  position: relative;
  isolation: isolate;
  display: grid;
  /* ⚠️ 行高**单一来源**（2026-10-19 用户实测缺陷修）：页眉/页脚带宽必须是 CSS 变量，
     因为**页眉内所有装饰都按 `--dh-band-h` 缩放**（见 `.dh-stage{font-size}`）——
     两处各写一份（变量与 grid 行）曾经漂移过，正是"带变矮而角色没缩"的根源。 */
  --dh-band-h: clamp(48px, 7.4vh, 80px);
  --dh-band-h-march: clamp(40px, 6vh, 64px);
  --dh-foot-h: clamp(44px, 6.5vh, 56px);
  --dh-band-cur: var(--dh-band-h);
  grid-template-rows: var(--dh-band-h) minmax(0, 1fr) var(--dh-foot-h);
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-width: 0;
  overflow: hidden;
  padding: 0 14px 6px;
  background: var(--reader-page-background);
}
.dh-marching {
  grid-template-rows: var(--dh-band-h-march) minmax(0, 1fr) var(--dh-foot-h);
  --dh-band-cur: var(--dh-band-h-march);
}

/* ⚠️ 横屏/矮屏断点（2026-10-19 真机口径实测发现）：本项目 MEmu 实例在 **横屏** 下
   物理 1600×1000 / density 300 ⇒ CSS 视口 **853×533**，而 `0.2×视口` 的"页眉+页脚"预算只有 **106.6px**
   ⇒ 上面竖屏那套（页眉 min 48 + 页脚 min 44）总占位 116px ⇒ 正文区仅 78.2%，**跌破 ≥80% 硬指标**。
   故矮屏另收一档（页眉 min 36 / 页脚 min 32）⇒ 实测 533 档：页眉 51.6 / 页脚 47 / 正文区 **81.5%**。
   密度仍靠层数补，不靠高度。 */
@media (max-height: 600px) {
  .dh-page {
    --dh-band-h: clamp(36px, 8vh, 52px);
    --dh-band-h-march: clamp(30px, 6.5vh, 44px);
    --dh-foot-h: clamp(32px, 6vh, 44px);
  }
}

/* 整页叠加层：暗角 + 石纹斜纹（z-index:-1，不参与测量） */
.dh-page::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(135deg, transparent 0 8px, rgba(0, 0, 0, calc(.05 * var(--dh-deco))) 8px 9px),
    radial-gradient(130% 70% at 50% -12%, rgba(0, 0, 0, calc(.30 * var(--dh-deco))) 0, transparent 62%),
    radial-gradient(100% 60% at 92% 110%, rgba(122, 28, 23, calc(.20 * var(--dh-deco))) 0, transparent 62%);
}
.dh-grain {
  position: absolute;
  z-index: -1;
  inset: 0;
  pointer-events: none;
  opacity: calc(.10 * var(--dh-deco));
  background: radial-gradient(rgba(0, 0, 0, .55) .4px, transparent .8px) 0 0/6px 6px;
}

/* —— 页眉 · 活场景：**游戏原图全幅铺底** + 暗幕 + 底部渐隐接纸页 ——
   ⚠️ **缩放体系（2026-10-19 用户实测缺陷修）**：`.dh-stage` 的 `font-size` 取**带宽的 1%**
   ⇒ **1em = 1% 页眉带高**，页眉内所有尺寸/位移一律改用 em ⇒ 带宽一变，整层装饰**等比缩放**。
   角色（主角 / 敌方 / NPC）的画布高度由构建期按「**墨迹 ≤ 88% 带高**」**从素材墨迹反推**
   （`build-dungeon-hud.py` 的 `sprite_geom`）⇒ 竖屏 / 横屏 / 任意尺寸下**角色都完整可见**。
   旧实现是写死 px + `transform: scale(1.3)`：带宽 63px（竖屏 480×853）时角色墨迹高达 108px
   ⇒ **被裁掉 40px**（用户截图实测「主角/怪物显示不全」——那条注释写"稳定不裁头"，与实测相反，已纠正）。 */
.dh-stage {
  position: relative;
  margin: -6px -14px 0;
  overflow: hidden;
  font-size: calc(var(--dh-band-cur) / 100);
  background-color: #08090b;
  background-image: var(--dh-scene);
  background-size: cover;
  background-position: 30% 42%;
  background-repeat: no-repeat;
}
/* 续页换景：同一张图换取景位 + 偏冷的幕（观感像换了场地，且零额外字节） */
.dh-marching .dh-stage { background-position: 76% 68% }
.dh-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(80% 120% at 50% 118%, rgba(122, 28, 23, calc(.30 * var(--dh-deco))) 0, transparent 58%),
    linear-gradient(180deg, rgba(4, 4, 6, .34) 0%, var(--dh-veil) 58%, var(--dh-fade) 100%);
}
.dh-sky { display: none }
/* 场景道具（原作建筑/陈设小图，绝对定位散布，不吃正文高度）——尺寸全部 em（随带高缩放） */
.dh-props { position: absolute; inset: 0; pointer-events: none; opacity: calc(.92 * var(--dh-deco)) }
.dh-props i { position: absolute; background-position: center bottom; background-size: contain; background-repeat: no-repeat }
.dh-prop-a { left: 4%; bottom: 0; width: 56em; height: 26em; background-image: url("data:image/png;base64,") }
.dh-prop-b { left: 27%; bottom: 2em; width: 10em; height: 24em; background-image: url("data:image/png;base64,") }
/* c / d 为 CSS 自绘的石柱与光台（不使用素材） */
.dh-prop-c { right: 4%; bottom: 0; width: 31em; height: 47em; background-image: linear-gradient(180deg, #4a4741, #171614); clip-path: polygon(20% 0, 80% 0, 100% 100%, 0 100%); opacity: .7 }
.dh-prop-d { right: 25%; bottom: 0; width: 56em; height: 23em; background-image: linear-gradient(180deg, #55514a, #201f1c); opacity: .65 }

/* 主角：12 层部件同帧号叠加。画布尺寸/精灵表/动画步距**全部 em**，且画布高由墨迹反推
   ⇒ 墨迹高度恒 = 88% 带高，脚底贴带底（`{{fig-bottom}}` 把墨迹下沿对齐到带底）。 */
.dh-rig { position: absolute; width: 190.8em; height: 190.8em; transform-origin: 50% 100% }
.dh-hero { left: 12%; bottom: -53.0em }
.dh-rig .dh-p {
  position: absolute;
  inset: 0;
  background-repeat: no-repeat;
  background-size: 1908.4em 190.8em;
  background-position: 0 0;
}
/* 层序（背 → 前）：躯体 → 腿脚 → 裙 → 胸 → 臂 → 头 → 发 → 披肩 */
.dh-p { background-image: none }
.dh-p-body { background-image: url("data:image/png;base64,") }
.dh-p-leg_left { background-image: url("data:image/png;base64,") }
.dh-p-leg_right { background-image: url("data:image/png;base64,") }
.dh-p-foot_left { background-image: url("data:image/png;base64,") }
.dh-p-foot_right { background-image: url("data:image/png;base64,") }
.dh-p-skirt { background-image: url("data:image/png;base64,") }
.dh-p-chest { background-image: url("data:image/png;base64,") }
.dh-p-arm_left { background-image: url("data:image/png;base64,") }
.dh-p-arm_right { background-image: url("data:image/png;base64,") }
.dh-p-head { background-image: url("data:image/png;base64,") }
.dh-p-hair { background-image: url("data:image/png;base64,") }
.dh-p-shoulder_right { background-image: url("data:image/png;base64,") }

/* 敌方：整帧序列（页眉 = 对峙，向主角方向推进）。画布 = 一帧的 em 尺寸，精灵表 em 宽
   （**不能 contain**：会破坏 `steps()` 的步进像素；改用"元素 = 帧尺寸"的纪律 + em 缩放）。 */
.dh-foe { position: absolute; transform-origin: 50% 100% }
.dh-foe .dh-f {
  position: absolute;
  inset: 0;
  background-repeat: no-repeat;
  background-position: 0 0;
  transform-origin: 50% 100%;
}
.dh-foe-boss { right: 10%; bottom: -93.9em; width: 109.4em; height: 190.3em }
.dh-foe-boss .dh-f { background-image: url("data:image/png;base64,"); background-size: 765.8em 190.3em }
.dh-foe-spider { left: 8%; bottom: -209.4em; width: 424.8em; height: 424.8em }
.dh-foe-spider .dh-f { background-image: url("data:image/png;base64,"); background-size: 1274.5em 424.8em }
/* 弹道（绝对定位，周期飞过，不占正文）—— R4 改用两帧精灵表，见 `.dh-fx-bolt`（旧 `.dh-bullet` 已删） */
/* 斩击闪光（CSS 自绘，不用素材）—— 类名 `dh-fx-slash` 与 HTML 一致（R4 统一到 `dh-fx` 族，
   避免"CSS 声明了类但 HTML 从不出现在"的死规则，这正是旧任务抓到的 `dh-c-bl`/`dh-c-tr` 同类缺陷） */
.dh-fx-slash {
  position: absolute;
  left: 34%;
  bottom: 10em;
  width: 64em;
  height: 40em;
  pointer-events: none;
  opacity: 0;
  border-top: 2em solid rgba(240, 236, 226, .92);
  border-radius: 50%;
  transform: rotate(-24deg);
}
/* 关卡/书名标牌（文字尺寸用 clamp：随带高缩放但**保底可读**，避免矮屏小到看不清） */
.dh-plate {
  position: absolute;
  left: 12em;
  bottom: 6em;
  display: flex;
  align-items: center;
  gap: 6em;
  padding: 3em 7em;
  background: rgba(6, 6, 8, .66);
  border: 1px solid rgba(201, 162, 74, calc(.55 * var(--dh-deco)));
  color: #e9e3d5;
  font-family: var(--reader-font-family);
  font-size: clamp(8px, calc(var(--dh-band-cur) * 0.10), 11px);
  letter-spacing: .06em;
}
.dh-plate b { font-size: .86em; letter-spacing: .18em; color: var(--dh-gold) }
.dh-plate span { max-width: 46%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis }
/* 牺牲场景（血条归零时显形；**不用原作剧情 CG** —— 以姿态/灯光/排字表达） */
.dh-requiem {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3em;
  opacity: 0;
  background: radial-gradient(70% 100% at 50% 100%, var(--dh-requiem-glow) 0, rgba(4, 3, 3, .80) 76%);
  color: #ecdfc6;
  pointer-events: none;
}
.dh-requiem b { font-size: clamp(7px, calc(var(--dh-band-cur) * 0.09), 10px); letter-spacing: .34em; color: var(--dh-hp) }
.dh-requiem em { font-style: normal; font-size: clamp(10px, calc(var(--dh-band-cur) * 0.15), 15px); letter-spacing: .30em }
.dh-page.dh-fallen .dh-requiem { opacity: 1 }
.dh-page.dh-fallen .dh-hero { filter: grayscale(1) brightness(.45); transform: rotate(12deg) translate(-6em, 12em) }
.dh-page.dh-fallen .dh-foe { filter: grayscale(.7) brightness(.55) }
.dh-page.dh-fallen .dh-fx-slash { opacity: 0 }

/* —— 正文纸页：**石色净面**（可读性优先） ——
   ⚠️ 2026-10-20 用户实测缺陷修（「阅读正文区域一大片阴影遮挡」，产物截图 `output/body_check.png` 可见）：
   此前纸页同时铺 `--dh-scene`（**整幅暗场景照片**，cover 取景位）+ `--dh-stone`（**深色石纹**），
   再盖 84% 幕 ⇒ 透出的深色图案在正文区形成**成片暗斑**，即用户感知的"阴影遮挡"。
   正文区**不得出现可辨图案**：场景照片一律撤出纸页（它只属于页眉场景带），石纹只作**极淡**纸面质感
   （配合 `--dh-veil-strong ≥ .95` ⇒ 残余透出 ≤5%，不构成视觉遮挡）。 */
.dh-paper {
  position: relative;
  z-index: 2;
  min-width: 0;
  min-height: 0;
  margin-top: 0;
  padding: 8px 15px 8px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--dh-paper-edge);
  background-color: var(--dh-paper);
  background-image: var(--dh-stone);
  background-size: 168px 168px;
  background-position: 0 0;
  background-repeat: repeat;
  box-shadow: 0 8px 22px rgba(0, 0, 0, calc(.28 * var(--dh-deco)));
}
.dh-paper::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  pointer-events: none;
  background: var(--dh-veil-strong);
}
.dh-frame { position: absolute; inset: 4px; pointer-events: none; border: 1px solid rgba(201, 162, 74, calc(.42 * var(--dh-deco))) }
.dh-corner { position: absolute; width: 14px; height: 14px; border: 2px solid var(--dh-gold); opacity: calc(.9 * var(--dh-deco)); pointer-events: none }
.dh-c-tl { left: -1px; top: -1px; border-right: 0; border-bottom: 0 }
.dh-c-tr { right: -1px; top: -1px; border-left: 0; border-bottom: 0 }
.dh-c-bl { left: -1px; bottom: -1px; border-right: 0; border-top: 0 }
.dh-c-br { right: -1px; bottom: -1px; border-left: 0; border-top: 0 }
.dh-tab {
  position: absolute;
  top: -9px;
  right: 16px;
  height: 18px;
  padding: 0 7px;
  display: flex;
  align-items: center;
  background: #1a1210;
  border: 1px solid rgba(201, 162, 74, calc(.5 * var(--dh-deco)));
  color: #d8b775;
  font-size: 9px;
  letter-spacing: .16em;
  pointer-events: none;
}
/* ⚠️ **正文槽必须有显式高度约束**（R2 主修，2026-10-19；archive 同款 `.as-flow{height:100%;min-height:0}`）：
   缺它时正文槽会随内容**自由增高** ⇒ 槽 `rect.bottom` 远超根壳底 ⇒ 引擎占位口径的「下占位」为**负值**
   （实测 −8341）⇒ 页框被算成**整章内容高**（实测 h=9020）⇒ 分页退化为"整章一屏"、`page`/`body` 恒 0
   ⇒ **双向翻页失效**（用户报"只能翻下一页、无法翻上一页"）。给了 `height:100%` 后槽高 = 纸页内容高
   ⇒ 下占位恒为正（= 页脚带占位）⇒ 页框回到"视口 − 占位"量级。
   冻结由引擎写入 inline `height`/`overflow`/`clip-path` ⇒ 该声明只在**未冻结的自然布局**下生效（量占位用）。 */
.dh-body {
  position: relative;
  z-index: 1;
  height: 100%;
  box-sizing: border-box;
  min-width: 0;
  min-height: 0;
  text-align: justify;
  --legado-highlight-room-left: 10px;
  --legado-highlight-room-right: 10px;
}
.reader-paragraph {
  position: relative;
  display: block;
  margin: 0 0 var(--reader-paragraph-spacing);
  text-indent: var(--reader-paragraph-indent);
  break-inside: auto;
  page-break-inside: auto;
  orphans: 1;
  widows: 1;
}
/* ===== 段落语义（对齐 archive 的 as-scene / as-dialogue / as-lead；2026-10-17 补齐）=====
 * 背景：archive 导出的主题都在 `beforeLayout` 里按**正文文本**给段落打语义类 —— 那是"分段正文样式"
 * 的可见主体；本主题此前只在 CSS 里写了 `.dh-lead` 规则，却**没有任何代码给它加类**（死规则）
 * ⇒ 与 archive 主题逐套比对时表现为「段落元素缺失」。
 * 分类由 `script.js` 的 classifyParagraphs 完成，阈值与 archive 同口径（同一段正文两边分类一致）。
 * 取值全走**主题三态变量**（--dh-gold / --dh-hp / --reader-accent）⇒ 日间 / 夜间 / 水墨屏各自成立。 */
.reader-paragraph.dh-scene {
  text-indent: 0;
  text-align: center;
  letter-spacing: .5em;
  font-size: .86em;
  color: var(--dh-gold);
}
/* 场景分隔段的**悬挂读数**（段序号，来自 JS 的 `data-dh-seq`）：绝对定位 ⇒ 不参与正文测量
   ⇔ 与 archive 主题的悬挂序号同构（那边也是装饰层不改变分页）。 */
.reader-paragraph.dh-scene::after {
  content: attr(data-dh-seq);
  position: absolute;
  left: 2px;
  top: .15em;
  font: 600 .62em/1 ui-monospace, Menlo, Consolas, monospace;
  letter-spacing: .12em;
  color: var(--dh-gold);
  opacity: calc(.55 * var(--dh-deco));
}
.reader-paragraph.dh-dialogue {
  border-left: 2px solid var(--dh-hp);
  padding-left: 9px;
  text-indent: 0;
}
.reader-paragraph.dh-lead:not([data-reader-continuation]):not([data-split-from]) { text-indent: 0 }
.reader-paragraph.dh-lead::first-line { color: var(--reader-accent); font-weight: 600 }
.reader-chapter-title {
  display: block;
  margin: .1em 0 .7em;
  padding-bottom: .5em;
  text-indent: 0;
  font-size: 1.3em;
  font-weight: 650;
  letter-spacing: .03em;
  border-bottom: 1px solid rgba(201, 162, 74, calc(.45 * var(--dh-deco)));
}
[data-reader-continuation], .reader-paragraph[data-split-from] { text-indent: 0 }
/* 续页底部对话框：CSS 自绘暗色切角框（省下 205KB 原作底图内联，底图预算让给全幅场景图） */
.dh-dialog {
  position: absolute;
  left: 6px;
  right: 6px;
  bottom: 6px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  background: linear-gradient(180deg, rgba(12, 12, 14, .93), rgba(6, 6, 8, .97));
  border: 1px solid rgba(201, 162, 74, calc(.42 * var(--dh-deco)));
  clip-path: polygon(0 5px, 5px 0, calc(100% - 5px) 0, 100% 5px, 100% calc(100% - 5px), calc(100% - 5px) 100%, 5px 100%, 0 calc(100% - 5px));
  color: #e6ded0;
  font-size: 11px;
  opacity: calc(.95 * var(--dh-deco));
}
.dh-dialog i { flex: none; width: 13px; height: 15px; background-image: var(--dh-bolt); background-size: 36px 15px; background-repeat: no-repeat; background-position: 0 0 }
.dh-dialog span { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis }
/* 对话框会压住正文末行 ⇒ 续页正文预留底部安全边距 */
.dh-marching .dh-body { padding-bottom: 34px }

/* —— 页脚 HUD：**游戏原图第三取景位铺底** + 红/蓝状态条 + 物品栏 + 读数 —— */
.dh-hud {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 6px;
  padding: 0 4px;
}
.dh-hud::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -5px 0 -8px;
  pointer-events: none;
  background-color: #0a0b0d;
  background-image: var(--dh-scene);
  background-size: cover;
  background-position: 46% 94%;
  background-repeat: no-repeat;
  opacity: calc(.62 + .0 * var(--dh-deco));
  border-top: 1px solid var(--dh-line);
}
.dh-bars { flex: 0 0 40%; display: flex; flex-direction: column; gap: 5px; min-width: 0 }
.dh-bar {
  position: relative;
  height: 9px;
  border: 1px solid var(--dh-line);
  background: rgba(8, 8, 10, .62);
  overflow: hidden;
}
.dh-bar .dh-fill { position: absolute; inset: 0 auto 0 0; width: 100% }
.dh-bar .dh-fill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 4px, rgba(0, 0, 0, .28) 4px 5px);
}
.dh-bar b {
  position: absolute;
  right: 3px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 6px;
  letter-spacing: .12em;
  color: #e8e2d6;
  opacity: .8;
}
/* 红条 = 整本剩余（宿主整书进度 --rp-percent ⇒ 读到末页归零） */
.dh-bar-hp .dh-fill { background: linear-gradient(90deg, rgba(122, 28, 23, .30), var(--dh-hp)); width: calc(100% - var(--rp-percent, 0) * 1%) }
/* 蓝条 = 本章/本页序列剩余（JS 下发 --dh-stamina） */
.dh-bar-mp .dh-fill { background: linear-gradient(90deg, rgba(57, 80, 106, .30), var(--dh-mp)); width: calc(var(--dh-stamina, 100) * 1%) }
.dh-slots { flex: 1 1 auto; display: flex; gap: 2px; min-width: 0; justify-content: flex-end }
.dh-slot {
  flex: none;
  width: 17px;
  height: 20px;
  border: 1px solid var(--dh-line);
  background-color: rgba(8, 8, 10, .55);
  background-position: center;
  background-size: contain;
  background-repeat: no-repeat;
  opacity: calc(.92 * var(--dh-deco));
}
.dh-s-active { border-color: var(--dh-gold); box-shadow: 0 0 0 1px rgba(201, 162, 74, calc(.5 * var(--dh-deco))) inset }
.dh-s-book { background-image: url("data:image/png;base64,") }
.dh-s-cage { background-image: url("data:image/png;base64,") }
.dh-s-barrel { background-image: url("data:image/png;base64,") }
.dh-s-box { background-image: url("data:image/png;base64,") }
.dh-s-chest { background-image: url("data:image/png;base64,") }
.dh-s-lectern { background-image: url("data:image/png;base64,") }
.dh-readout {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  line-height: 1.2;
}
.dh-folio { font-size: 14px; font-weight: 700; font-variant-numeric: tabular-nums; color: #e9e3d5 }
.dh-folio em { font-style: normal; color: var(--dh-dim); font-size: 10px }
.dh-folio span { font-size: 10px; color: var(--dh-dim) }
.dh-time { font-size: 8px; letter-spacing: .16em; color: var(--dh-dim) }

/* 浮尘：绝对定位细粒（不参与测量） */
.dh-motes { position: absolute; inset: 0; z-index: 3; overflow: hidden; pointer-events: none }
.dh-motes i {
  position: absolute;
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background: rgba(222, 208, 176, calc(.72 * var(--dh-deco)));
}
.dh-motes i:nth-child(1) { left: 18%; bottom: 18% }
.dh-motes i:nth-child(2) { left: 44%; bottom: 12% }
.dh-motes i:nth-child(3) { left: 68%; bottom: 22% }
.dh-motes i:nth-child(4) { left: 82%; bottom: 9% }
.dh-motes i:nth-child(5) { left: 32%; bottom: 30% }

/* ============ R4 区域 · 演出态 · 竖带 · NPC · 技能特效（2026-10-19 扩容）============
   为什么用**属性驱动**：模板运行时只给 `firstPageHtml` / `otherPageHtml` 两个 HTML 通道
   （没有"第 3 个壳"）⇒ 区域与演出态只能由作者 JS 写在**同一份 HTML** 的 `data-dh-*` 上，
   CSS 按属性切片。判别：`data-dh-region` ∈ {cathedral, town, grave, cave}；
        `data-dh-perf` ∈ {explore 探索, battle 打怪, talk 对话}；末页另有 `.dh-fallen`。 */

/* —— 区域底图与调色（4 区域；素材侧只有约 4 类场景 ⇒ 不做 8 张独立底图，见 design AD-8 第 10 条） —— */
.dh-page[data-dh-region="cathedral"] .dh-stage { background-image: var(--dh-scene); background-position: 30% 42% }
.dh-page[data-dh-region="town"] .dh-stage { background-image: var(--dh-town); background-position: 42% 34% }
.dh-page[data-dh-region="town"] { --dh-paper: #a9a49a; --dh-paper-edge: #6f6b64; --reader-page-background: #b0aba1 }
.dh-page[data-dh-region="grave"] .dh-stage { background-image: var(--dh-grave); background-position: 50% 58% }
.dh-page[data-dh-region="grave"] { --dh-paper: #a5a29b; --dh-paper-edge: #64635e; --reader-page-background: #aaa79f }
.dh-page[data-dh-region="cave"] .dh-stage {
  background-image: var(--dh-stone);
  background-size: 96px 96px;
  background-repeat: repeat;
  background-position: 0 0
}
.dh-page[data-dh-region="cave"] { --dh-paper: #9d9c99; --dh-paper-edge: #5c5c5a; --reader-page-background: #a3a29f }

/* —— 区域专属**敌方阵容**（≥4 种；只有本区域那一种上场）+ 演出态开关 —— */
.dh-foe { opacity: 0 }
.dh-page[data-dh-region="cathedral"] .dh-foe-boss { opacity: 1 }
.dh-page[data-dh-region="town"] .dh-foe-spider { opacity: 1 }
.dh-page[data-dh-region="grave"] .dh-foe-slug { opacity: 1 }
.dh-page[data-dh-region="cave"] .dh-foe-frog { opacity: 1 }
/* 对话演出：清场（无敌人）并把 NPC 请上场；探索态敌人半隐；只有打怪态出技能特效 */
.dh-page[data-dh-perf="talk"] .dh-foe { opacity: 0 }
.dh-page[data-dh-perf="explore"] .dh-foe { opacity: .38 }
.dh-page[data-dh-perf="talk"] .dh-npc { opacity: 1 }
.dh-page[data-dh-perf="battle"] .dh-npc { opacity: 0 }
.dh-page[data-dh-perf="talk"] .dh-fx { opacity: 0 }
.dh-page[data-dh-perf="explore"] .dh-fx { opacity: 0 }
.dh-page[data-dh-perf="talk"] .dh-talk { opacity: calc(.95 * var(--dh-deco)) }
.dh-page.dh-fallen .dh-talk { opacity: 0 }

/* —— R4 敌方 ③④：小型黏液怪 / 蛙形怪（画布与精灵表**全部 em** ⇒ 与页眉带等比缩放并完整可见） —— */
.dh-foe-slug { left: 5%; bottom: -249.3em; width: 880.0em; height: 880.0em }
.dh-foe-slug .dh-f { background-image: url("data:image/png;base64,"); background-size: 6160.0em 880.0em }
.dh-foe-frog { right: 5%; bottom: -56.6em; width: 202.4em; height: 202.4em }
.dh-foe-frog .dh-f { background-image: url("data:image/png;base64,"); background-size: 1012.0em 202.4em }

/* —— R4 NPC（对话演出在场者）：2 帧整身动图（分层部件合成）——同样 em 缩放 —— */
.dh-npc {
  position: absolute;
  left: 62%;
  bottom: -60.6em;
  width: 214.1em;
  height: 214.1em;
  transform-origin: 50% 100%;
  opacity: 0;
}
.dh-npc .dh-n-f {
  position: absolute;
  inset: 0;
  background-image: url("data:image/png;base64,");
  background-size: 428.1em 214.1em;
  background-repeat: no-repeat;
  background-position: 0 0
}

/* —— R4 左右两侧**竖区域**点缀（对齐 archive 左右竖带；图集四格各取一格）——
   ⚠️ **这里是"页面级"元素（`.dh-band` 在 `<header class="dh-stage">` 之外）** ⇒ 单位**不得用 em**：
   本项目 em 的语义是「1em = 1% 页眉带高」（由 `.dh-stage{font-size:calc(var(--dh-band-cur)/100)}` 定义），
   而本容器不在带内 ⇒ 它的 em 会按**正文行高基准（18px）**解析 ⇒ `20em×30em = 360×540px` 的四块大图
   直接糊在正文区上（2026-10-20 用户实测「正文区一大片阴影遮挡」的**根因**，属本轮 em 改造引入的回归）。
   故此处一律用 **px 绝对值**（竖带是"贴页左右边缘的窄条"，与带宽无关）。 */
.dh-band { position: absolute; top: 0; bottom: 0; width: 22px; z-index: 3; pointer-events: none }
.dh-band-l { left: 0 }
.dh-band-r { right: 0 }
.dh-band i {
  position: absolute;
  width: 20px;
  height: 30px;
  background-image: var(--dh-band);
  background-repeat: no-repeat;
  background-size: 400% 100%;
  opacity: calc(.85 * var(--dh-deco))
}
.dh-b0 { left: 1px; top: 16%; background-position: 0% 50% }
.dh-b1 { left: 1px; top: 52%; background-position: 33.33% 50% }
.dh-b2 { right: 1px; top: 28%; background-position: 66.67% 50% }
.dh-b3 { right: 1px; top: 64%; background-position: 100% 50% }

/* —— R4 技能/弹道特效 3 类（斩击=CSS / 多帧弹道=精灵表 / 冲击波=CSS） —— */
.dh-fx { position: absolute; pointer-events: none; opacity: 0 }
.dh-fx-bolt { left: 30%; top: 42%; width: 14em; height: 15em }
/* 多帧弹道：两帧精灵表 + `steps(2)`（元素盒 = 帧尺寸 ⇒ 步进像素不错位） */
.dh-fx-bolt i {
  display: block;
  width: 100%;
  height: 100%;
  background-image: var(--dh-bolt);
  background-size: 211.2em 88.0em;
  background-repeat: no-repeat;
  background-position: 0 0
}
.dh-fx-burst {
  left: 40%;
  bottom: 7em;
  width: 84em;
  height: 49em;
  background: radial-gradient(50% 50% at 50% 50%, rgba(236, 223, 198, calc(.75 * var(--dh-deco))) 0, rgba(122, 28, 23, calc(.42 * var(--dh-deco))) 42%, transparent 72%)
}
.dh-page[data-dh-perf="battle"] .dh-fx-slash { opacity: 1 }
.dh-page[data-dh-perf="battle"] .dh-fx-bolt { opacity: calc(var(--dh-deco)) }
.dh-page[data-dh-perf="battle"] .dh-fx-burst { opacity: calc(.9 * var(--dh-deco)) }

/* —— R4 对话气泡（NPC 演出时的台词框；绝对定位 ⇒ 不参与正文测量） ——
   ⚠️ 位置避让（产物截图自验发现）：气泡原为 `left: 8px; right: 8px` 全幅贴底，
   与左下角的**关卡标牌** `.dh-plate`（`left:14px; bottom:7px`）**文字重叠**（截图上两行字叠在一起）。
   故改为**只在右半幅**（`left: 40%`），把左下角留给标牌。 */
.dh-talk {
  position: absolute;
  left: 40%;
  right: 8em;
  bottom: 4em;
  display: flex;
  align-items: center;
  gap: 6em;
  padding: 3em 9em;
  background: linear-gradient(180deg, rgba(12, 12, 14, calc(.92 * var(--dh-deco))), rgba(6, 6, 8, calc(.96 * var(--dh-deco))));
  border: 1px solid rgba(201, 162, 74, calc(.42 * var(--dh-deco)));
  color: #e6ded0;
  font-size: clamp(8px, calc(var(--dh-band-cur) * 0.10), 11px);
  opacity: 0
}
.dh-talk b { flex: none; font-size: .78em; letter-spacing: .18em; color: var(--dh-gold) }
.dh-talk span { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis }

/* 幽夜回廊 · 动效（逐帧精灵动画 / 战斗节奏 / 浮尘 / 牺牲场景 / 进页动效）
   纪律（对齐 archive）：只做有限动效、无计时器、无 WebGL；`html[data-reader-motion="paused"]` 即全部停摆。 */

/* 主角：12 层部件共用一个 steps(10) 时间基 ⇒ 严格同步（步距 = 整表 em 宽，随页眉带高缩放） */
@keyframes dh-walk { from { background-position: 0 0 } to { background-position: -1908.4em 0 } }

/* 敌方逐帧序列（整帧精灵表横向拼接，像素零改动） */
@keyframes dh-boss { from { background-position: 0 0 } to { background-position: -765.8em 0 } }
@keyframes dh-spider { from { background-position: 0 0 } to { background-position: -1274.5em 0 } }

/* R4 新增：敌方 ③④ 与 NPC 的逐帧序列（帧宽高由构建期占位符注入 ⇒ 换素材不会静默错位） */
@keyframes dh-slug { from { background-position: 0 0 } to { background-position: -6160.0em 0 } }
@keyframes dh-frog { from { background-position: 0 0 } to { background-position: -1012.0em 0 } }
@keyframes dh-npc { from { background-position: 0 0 } to { background-position: -428.1em 0 } }
/* 弹道两帧（`steps()` 真动图的"技能特效"实现通道） */
@keyframes dh-bolt { from { background-position: 0 0 } to { background-position: -211.2em 0 } }

/* 回合推进：敌方在页眉内向主角方向压近（原地往返，不触发整页重排） */
@keyframes dh-advance { 0% { transform: translateX(0) } 100% { transform: translateX(-19em) } }

/* 斩击闪光（CSS 自绘；不用素材） */
@keyframes dh-slash {
  0%, 72% { opacity: 0; transform: rotate(-24deg) scaleX(.2) }
  80% { opacity: .95; transform: rotate(-24deg) scaleX(1) }
  90%, 100% { opacity: 0; transform: rotate(-24deg) scaleX(1.12) }
}

/* 弹道飞行（一次飞行 = 一条弧线；循环即"下一发"，无累积对象） */
@keyframes dh-flight {
  0% { transform: translate(0, 0); opacity: 0 }
  14% { opacity: 1 }
  62% { transform: translate(178px, -26px); opacity: 1 }
  72%, 100% { transform: translate(214px, -34px); opacity: 0 }
}

/* 浮尘上升（位移用 em ⇒ 随页眉带高缩放） */
@keyframes dh-rise {
  0% { transform: translate(0, 0); opacity: 0 }
  42% { opacity: .9 }
  100% { transform: translate(5em, -42em); opacity: 0 }
}

/* 牺牲场景渐显 */
@keyframes dh-requiem-in { from { opacity: 0 } to { opacity: 1 } }

/* —— 挂载 —— */
.dh-rig .dh-p { animation: dh-walk .82s steps(10) infinite }
.dh-foe-boss .dh-f { animation: dh-boss .72s steps(7) infinite }
.dh-foe-boss { animation: dh-advance 3s ease-in-out infinite alternate }
.dh-foe-spider .dh-f { animation: dh-spider .94s steps(3) infinite }
.dh-foe-spider { animation: dh-advance 3.8s ease-in-out infinite alternate }
.dh-fx-slash { animation: dh-slash 2.6s ease-out infinite }
.dh-fx-bolt { animation: dh-flight 3.4s linear infinite }
/* R4：敌方 ③④ / NPC / 弹道特效的逐帧序列挂载（步数与素材帧数严格一致） */
.dh-foe-slug .dh-f { animation: dh-slug 1.1s steps(7) infinite }
.dh-foe-frog .dh-f { animation: dh-frog .9s steps(5) infinite }
.dh-npc .dh-n-f { animation: dh-npc 1.4s steps(2) infinite }
.dh-fx-bolt i { animation: dh-bolt .5s steps(2) infinite }
.dh-motes i { animation: dh-rise 5.2s ease-in-out infinite }
.dh-page.dh-fallen .dh-requiem { animation: dh-requiem-in .6s ease-out both }

/* 浮尘错相位（动画延迟不计入声明预算） */
.dh-motes i:nth-child(2) { animation-delay: -1s }
.dh-motes i:nth-child(3) { animation-delay: -2.2s }
.dh-motes i:nth-child(4) { animation-delay: -3.1s }
.dh-motes i:nth-child(5) { animation-delay: -4.3s }
.dh-foe-spider { animation-delay: -.6s }
.dh-fx-bolt { animation-delay: -1.4s }

/* 进页动效（archive 契约 R6：data-reader-entry pending → playing）：用过渡实现，不额外占帧序列预算 */
.dh-hero, .dh-paper, .dh-hud, .dh-stage { transition: opacity .5s ease-out }
.dh-hero, .dh-hud { transition-delay: .1s }
[data-reader-entry="pending"] .dh-hero,
[data-reader-entry="pending"] .dh-paper,
[data-reader-entry="pending"] .dh-hud,
[data-reader-entry="pending"] .dh-stage { opacity: 0; transition: none }

/* 动效闸门：专注模式 / 水墨屏 / 省电 ⇒ running→paused 时全部停摆并保留姿态 */
html[data-reader-motion="paused"] .dh-page,
html[data-reader-motion="paused"] .dh-page * { animation-play-state: paused }

/* 尊重系统"减少动态效果"：整页动效静默，静态帧与装饰保留（观感不塌） */
@media (prefers-reduced-motion: reduce) {
  .dh-page, .dh-page * { animation: none !important }
  .dh-hero, .dh-paper, .dh-hud, .dh-stage { transition: none !important; opacity: 1 !important }
}

javascript:
/* 幽夜回廊 · 行为脚本
   ①段落语义分类（首段 / 对白段 / 场景分隔段，对齐 archive 的 as-lead / as-dialogue / as-scene）
   ②蓝条（本章/本页序列剩余）随翻页递减 ③红条走后端整书进度（CSS 侧 --rp-percent）
   ④整书进度触顶 ⇒ 页眉切「牺牲场景」 ⑤只读语义、无网络、无宿主对象。 */
(function () {
  var rt = window.readerTemplate;
  if (!rt) return;

  var FALLEN_AT = 99.5;

  /**
   * 取**页面壳**（`.dh-page`）。
   *
   * ⚠️ 不能用 `readerTemplate.source` —— 运行时的 `source` 是**正文根**
   * （`data-reader-flow="body"` 的那个元素，见 template-runtime.js 的 `get source()`），
   * 拿它去找 `.dh-page` 会恒为 null（壳是它的**祖先**）⇒ 脚本静默空转。
   * 正确取法：作者根 `#reader-template-root` 下的外壳（换壳会整块替换，故每次都要现取）。
   */
  function shell(event) {
    if (event && event.page && event.page.querySelector) {
      var viaEvent = event.page.querySelector('.dh-page');
      if (viaEvent) return viaEvent;
    }
    var root = document.getElementById('reader-template-root');
    if (!root) return null;
    if (root.classList && root.classList.contains('dh-page')) return root;
    return root.querySelector('.dh-page');
  }

  /** 整书进度（优先取运行时下发的 --rp-percent，取不到再退回宿主字段）。 */
  function progressNow() {
    var raw = '';
    try {
      raw = getComputedStyle(document.documentElement).getPropertyValue('--rp-percent');
    } catch (error) {
      raw = '';
    }
    var value = parseFloat(raw);
    if (isNaN(value)) {
      var fields = rt.fields || {};
      value = typeof fields.progress === 'number' ? fields.progress : 0;
    }
    return value;
  }

  /** R4 导演：把**分页序号**映射为「区域」与「演出态」，写在页壳的 `data-dh-*` 上由 CSS 切片。
   *
   *  为什么必须在 JS 里做：模板运行时只提供 `firstPageHtml` / `otherPageHtml` 两个 HTML 通道
   *  （没有"第 3 个壳"）⇒ "多区域 / 多演出态"只能靠**同一份 HTML + 属性驱动**（见 spec R4 第 12 条）。
   *
   *  映射纪律（保证观感"推进"而不是"闪烁"）：
   *   · **区域**按**章内进度**分四段（4 区轮换，`cathedral → town → grave → cave`）
   *     ⇒ 一次翻页不会跳区；`pageChange`/`beforePage` 上都调用（换壳会整块替换页壳，属性会丢）。
   *   · **演出态**按页号轮换（探索 / 打怪 / 对话）；**末页恒为对话**（收束），
   *     与 `.dh-fallen`（牺牲场景）共同承担"结尾演出"。
   *  幂等：属性不变则不写（避免无谓的属性变更触发样式重算）。 */
  var REGIONS = ['cathedral', 'town', 'grave', 'cave'];
  var PERFS = ['explore', 'battle', 'talk'];
  function direct(event) {
    var root = shell(event);
    if (!root || !root.setAttribute) return;
    var total = rt.pageCount > 0 ? rt.pageCount : 1;
    var index = rt.pageIndex >= 0 ? rt.pageIndex : 0;
    var perRegion = Math.max(1, Math.ceil(total / REGIONS.length));
    var region = REGIONS[Math.min(REGIONS.length - 1, Math.floor(index / perRegion))];
    var perf = index >= total - 1 ? 'talk' : PERFS[index % PERFS.length];
    if (root.getAttribute('data-dh-region') !== region) root.setAttribute('data-dh-region', region);
    if (root.getAttribute('data-dh-perf') !== perf) root.setAttribute('data-dh-perf', perf);
  }

  /** 同步蓝条与牺牲场景。幂等：可被任意钩子重复调用。 */
  function sync(event) {
    var root = shell(event);
    if (!root) return;
    direct(event);
    var total = rt.pageCount > 0 ? rt.pageCount : 1;
    var read = Math.min(1, (rt.pageIndex + 1) / total);
    root.style.setProperty('--dh-stamina', String(Math.max(0, (1 - read) * 100)));
    // 红条 = 整本剩余（宿主 --rp-percent）⇒ 读到末页它本就该归零。
    // 两个判据取"或"：宿主进度可能滞后一帧，而"已到末页"是沙箱自己算得准的末态；
    // 二者语义同源（末页 ⇔ 剩余 0），故合成一个判据，避免"分明读完了却没进牺牲场景"。
    var atLastPage = rt.pageCount > 0 && rt.pageIndex >= rt.pageCount - 1;
    var fallen = progressNow() >= FALLEN_AT || atLastPage;
    var marked = root.className.indexOf('dh-fallen') >= 0;
    if (fallen !== marked) root.classList.toggle('dh-fallen', fallen);
  }

  /**
   * 段落语义分类（**"分段正文样式"的可见主体**，2026-10-17 补齐）。
   *
   * 为什么必须有：archive 导出的主题无一例外都在 `beforeLayout` 里按**正文文本**给段落打语义类
   * （首段 / 对白段 / 场景分隔段），CSS 再据此给首行加重、对白描边、场景居中留白。本主题此前
   * 只在 CSS 里声明了 `.dh-lead` 规则，**没有任何代码给它加类** ⇒ 规则恒空（死规则），
   * 与 archive 主题逐套比对时正是用户报的「段落元素缺失」。
   *
   * 分类阈值**与 archive 严格同口径**（`/^[*＊※·•—_\-\s]{3,}$/` 判场景分隔；`/^[“「『"]/` 判对白；
   * 本章首个非分隔段判首段）⇒ 同一段正文在本主题与 archive 主题里得到**同一分类**，
   * 保证"导入导出 + 换主题"后分段观感连续，而不是各家一套判据。
   *
   * 时机：正文由运行时注入后才发 `beforeLayout`（首屏）与 `beforePage`（**换壳**后重新注入正文），
   * 二者都要挂 —— 只挂前者会让续页壳里的段落丢类（首屏有、翻页后没了）。
   * 幂等：`classList.toggle` 与 `data-dh-seq` 的一次性写入都可重复调用。
   */
  function classifyParagraphs() {
    var source = rt.source;                       // 正文根（与 archive 的 readerTemplate.source 同义）
    if (!source || !source.querySelectorAll) return 0;
    var paragraphs = source.querySelectorAll('.reader-paragraph');
    var lead = true, seq = 0;
    for (var i = 0; i < paragraphs.length; i++) {
      var p = paragraphs[i];
      var text = (p.textContent || '').trim();
      var scene = /^[*＊※·•—_\-\s]{3,}$/.test(text);
      p.classList.toggle('dh-scene', scene);
      p.classList.toggle('dh-dialogue', /^[“「『"]/.test(text));
      var isLead = lead && !!text && !scene;
      p.classList.toggle('dh-lead', isLead);
      if (text && !scene) lead = false;
      // 段序号（场景分隔段不编号）：供 CSS 侧做"悬挂读数"类装饰，重复调用不重号
      if (!p.hasAttribute('data-dh-seq')) p.setAttribute('data-dh-seq', String(++seq));
    }
    return paragraphs.length;
  }

  rt.on('beforeLayout', classifyParagraphs);
  rt.on('beforePage', classifyParagraphs);
  rt.on('beforeLayout', sync);
  rt.on('afterLayout', sync);
  rt.on('pageChange', sync);
  rt.on('fieldsChange', sync);

  // 换壳（C1）会整块替换作者根壳：新壳上的动画必须重新起，这里借 motionChange 再同步一次。
  rt.on('motionChange', function () {
    sync();
  });

  rt.on('dispose', function () {
    var root = shell();
    if (!root) return;
    root.classList.remove('dh-fallen');
    root.style.removeProperty('--dh-stamina');
  });

  sync();
})();
